# Rule: find the special color (second least common), fill from boundary to it with 1s,
# convert special color to 4

def solve(grid):
    rows, cols = len(grid), len(grid[0])

    # Find colors
    from collections import Counter
    all_cells = [grid[r][c] for r in range(rows) for c in range(cols)]
    counter = Counter(all_cells)

    # Background is most common
    background = counter.most_common(1)[0][0]

    # Find special color (non-background, second least common? or least common)
    non_bg = [(c, count) for c, count in counter.items() if c != background]
    special_color = min(non_bg, key=lambda x: x[1])[0]  # Least common non-background

    # Find marker color (border color?)
    # Look for border with uniform color
    marker_candidates = []
    for col in range(cols):
        if col == 0 or col == cols-1:
            right_vals = set(grid[r][col] for r in range(rows))
            if len(right_vals) == 1 and right_vals.pop() != background:
                marker_candidates.append((col, grid[0][col]))
    marker_col = None
    marker_color = None
    for col, color in marker_candidates:
        marker_col, marker_color = col, color
        break

    if marker_col is None:
        # Try left and right edges
        for col in range(cols):
            if col == 0:
                vals = set(grid[r][col] for r in range(rows))
            elif col == cols - 1:
                vals = set(grid[r][col] for r in range(rows))
            else:
                continue
            if len(vals) == 1 and vals.pop() != background:
                marker_col, marker_color = col, list(vals)[0]
                break

    new_grid = [row[:] for row in grid]

    # For each row with marker
    for r in range(rows):
        # Check if this row has marker at left
        if new_grid[r][0] == marker_color:
            # Find special color in this row
            spec_pos = -1
            for c in range(1, cols):
                if grid[r][c] == special_color:
                    spec_pos = c
                    break

            # Fill from col 1 to spec_pos-1 with 1s, and turn special to 4
            if spec_pos > 1:
                for c in range(1, spec_pos):
                    new_grid[r][c] = 1
            if spec_pos > 0:
                new_grid[r][spec_pos] = 4

    return new_grid

