def solve_pair(grid):
    """
    Rule: Find rows with special marker at either left edge OR right edge.
    Rows with marker at col 0 + rows with marker at last col define the fill region.
    Fill marker columns (col 2 and col 6 for 7-col grid) with marker color.
    Rows with marker at both get col 2 filled with marker+2 at marked position.
    """
    rows, cols = len(grid), len(grid[0])
    cnt = Counter(x for r in grid for x in r)
    bg = cnt.most_common(1)[0][0]

    # Find rows with marker at edge
    left_markers = [(r, grid[r][0]) for r in range(rows) if grid[r][0] != bg]
    right_markers = [(r, grid[r][-1]) for r in range(rows) if grid[r][-1] != bg]

    if not left_markers or not right_markers:
        return grid[:][:]

    # Marker color comes from left markers
    marker_color = set(m[1] for m in left_markers)

    new_grid = [row[:] for row in grid]

    # Determine fill region: between min and max marker rows
    all_marker_rows = set(r for r, _ in left_markers) | set(r for r, _ in right_markers)
    min_r = min(all_marker_rows)
    max_r = max(all_marker_rows)

    # For each row between min_r and max_r, fill the marker columns
    marker_col_left = 2  # Looking at pair 0: col 2 and col 6 are filled
    marker_col_right = 6

    for r in range(min_r, max_r + 1):
        # Check if row has marker at left or right
        has_left = r in {m[0] for m in left_markers}
        has_right = r in {m[0] for m in right_markers}

        # Fill marker columns with marker_color if row has any marker
        if has_left or has_right:
            # But don't overwrite existing non-bg values
            for c in [0, 2, 6]:
                if c < cols and new_grid[r][c] == bg:
                    new_grid[r][c] = marker_color

        # Special handling for left marker row: convert corner from marker_color to 4
        for m in left_markers:
            if m[0] == r:
                # Find original marker color position
                orig_color = m[1]
                for c in range(1, cols - 1):
                    if new_grid[r][c] == orig_color:
                        new_grid[r][c] = marker_color

    return new_grid

